solution.resistor_color_expert.zig:
const std = @import("std");
const colors = [_][]const u8{ "black", "brown", "red", "orange", "yellow", "green", "blue", "violet", "grey", "white" };
fn digit(c: []const u8) !u64 {
    for (colors, 0..) |s, i| {
        if (std.mem.eql(u8, c, s)) return i;
    }
    return error.InvalidColor;
}
pub fn label(a: std.mem.Allocator, bands: []const []const u8) ![]u8 {
    if (bands.len == 1 and std.mem.eql(u8, bands[0], "black")) return a.dupe(u8, "0 ohms");
    if (bands.len != 4 and bands.len != 5) return error.InvalidBands;
    var n: u64 = 0;
    for (bands[0 .. bands.len - 2]) |c| n = n * 10 + try digit(c);
    const p = try digit(bands[bands.len - 2]);
    for (0..p) |_| n *= 10;
    const tolerances = [_][]const u8{ "grey", "violet", "blue", "green", "brown", "red", "gold", "silver" };
    const values = [_][]const u8{ "0.05", "0.1", "0.25", "0.5", "1", "2", "5", "10" };
    var tolerance: ?[]const u8 = null;
    for (tolerances, values) |c, v| {
        if (std.mem.eql(u8, c, bands[bands.len - 1])) tolerance = v;
    }
    const tol = tolerance orelse return error.InvalidTolerance;
    const unit: []const u8 = if (n >= 1000000000) "gigaohms" else if (n >= 1000000) "megaohms" else if (n >= 1000) "kiloohms" else "ohms";
    const divisor: u64 = if (n >= 1000000000) 1000000000 else if (n >= 1000000) 1000000 else if (n >= 1000) 1000 else 1;
    if (n % divisor == 0) return std.fmt.allocPrint(a, "{d} {s} ±{s}%", .{ n / divisor, unit, tol });
    return std.fmt.allocPrint(a, "{d} {s} ±{s}%", .{ @as(f64, @floatFromInt(n)) / @as(f64, @floatFromInt(divisor)), unit, tol });
}

