tests.test_resistor_color_expert.zig:
// Test scenarios adapted from the MIT-licensed Exercism Python track and
// exercism/problem-specifications (4289d4ec9ed947cd785939ab82c479bb8d4f2cc7).
const std = @import("std");
const t = std.testing;
const m = @import("resistor_color_expert.zig");
fn check(b: []const []const u8, e: []const u8) !void {
    const s = try m.label(t.allocator, b);
    defer t.allocator.free(s);
    try t.expectEqualStrings(e, s);
}
test "one four and five bands with units and tolerances" {
    try check(&.{"black"}, "0 ohms");
    try check(&.{ "orange", "orange", "black", "green" }, "33 ohms ±0.5%");
    try check(&.{ "orange", "orange", "red", "grey" }, "3.3 kiloohms ±0.05%");
    try check(&.{ "orange", "red", "orange", "blue", "violet" }, "323 megaohms ±0.1%");
    try check(&.{ "blue", "violet", "blue", "silver" }, "67 megaohms ±10%");
    try check(&.{ "white", "white", "white", "white", "gold" }, "999 gigaohms ±5%");
}
test "python test_orange_orange_black_and_red" {
    try check(&.{ "orange", "orange", "black", "red" }, "33 ohms ±2%");
}
test "python test_blue_grey_brown_and_violet" {
    try check(&.{ "blue", "grey", "brown", "violet" }, "680 ohms ±0.1%");
}
test "python test_red_black_red_and_green" {
    try check(&.{ "red", "black", "red", "green" }, "2 kiloohms ±0.5%");
}
test "python test_green_brown_orange_and_grey" {
    try check(&.{ "green", "brown", "orange", "grey" }, "51 kiloohms ±0.05%");
}
test "python test_one_black_band" {
    try check(&.{"black"}, "0 ohms");
}
test "python test_orange_orange_yellow_black_and_brown" {
    try check(&.{ "orange", "orange", "yellow", "black", "brown" }, "334 ohms ±1%");
}
test "python test_red_green_yellow_yellow_and_brown" {
    try check(&.{ "red", "green", "yellow", "yellow", "brown" }, "2.54 megaohms ±1%");
}
test "python test_blue_grey_white_brown_and_brown" {
    try check(&.{ "blue", "grey", "white", "brown", "brown" }, "6.89 kiloohms ±1%");
}
test "python test_violet_orange_red_and_grey" {
    try check(&.{ "violet", "orange", "red", "grey" }, "7.3 kiloohms ±0.05%");
}
test "python test_brown_red_orange_green_and_blue" {
    try check(&.{ "brown", "red", "orange", "green", "blue" }, "12.3 megaohms ±0.25%");
}
test "python test_brown_black_brown_yellow_and_violet" {
    try check(&.{ "brown", "black", "brown", "yellow", "violet" }, "1.01 megaohms ±0.1%");
}
test "python test_brown_black_red_and_red" {
    try check(&.{ "brown", "black", "red", "red" }, "1 kiloohms ±2%");
}
